"""wsync 的底层文件系统操作。

所有直接接触磁盘的调用都集中在本模块，这样文件属性、路径形式和共享
冲突的处理就只有一个地方需要关心。
"""

from __future__ import annotations

import hashlib
import os
import shutil
import stat
import sys
from typing import Dict, Optional, Tuple

__all__ = [
    "join",
    "path_key",
    "list_entries",
    "stat_signature",
    "compute_file_hash",
    "is_readonly",
    "clear_readonly",
    "remove_file",
    "remove_tree",
    "remove_any",
    "copy_file",
    "prune_empty_dirs",
    "ensure_parent_is_dir",
]


def join(root: str, relpath: str) -> str:
    """把目标根目录和一个相对路径拼成绝对路径。"""
    return os.path.join(root, relpath)


def path_key(relpath: str) -> str:
    """把相对路径规整成用于比较的键。

    目标平台的文件系统如何认定"两个路径写的是同一个东西"，由本函数
    决定；调用方不应自己再做字符串拼比较。
    """
    normalized = relpath.replace("/", os.sep)
    # Windows 文件系统不区分大小写
    if sys.platform == "win32":
        normalized = normalized.lower()
    return normalized


def list_entries(root: str) -> Dict[str, str]:
    """列出目录树中的所有普通文件。

    返回 ``{规范化相对路径: 绝对路径}``；``root`` 不存在时返回空字典。
    """
    entries: Dict[str, str] = {}
    if not os.path.isdir(root):
        return entries
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            relpath = os.path.relpath(full, root)
            # 使用规范化的键
            key = path_key(relpath)
            entries[key] = full
    return entries


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    """返回用于"内容是否变化"判定的签名。

    签名由大小与修改时间共同构成；读取失败时返回 ``None``。
    """
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def compute_file_hash(path: str) -> Optional[str]:
    """计算文件内容的 SHA256 哈希。

    读取失败时返回 ``None``。
    """
    try:
        hasher = hashlib.sha256()
        with open(path, "rb") as f:
            while True:
                chunk = f.read(1024 * 1024)
                if not chunk:
                    break
                hasher.update(chunk)
        return hasher.hexdigest()
    except OSError:
        return None


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def clear_readonly(path: str) -> None:
    """清除路径的只读属性（如果有的话）。"""
    try:
        if is_readonly(path):
            current_mode = os.stat(path).st_mode
            os.chmod(path, current_mode | stat.S_IWRITE)
    except OSError:
        pass


def remove_file(path: str) -> None:
    """删除单个文件。"""
    clear_readonly(path)
    os.remove(path)


def remove_tree(path: str) -> None:
    """递归删除一棵目录树。"""
    # 需要递归清除所有只读属性
    for root, dirs, files in os.walk(path, topdown=False):
        for name in files:
            clear_readonly(os.path.join(root, name))
        for name in dirs:
            clear_readonly(os.path.join(root, name))
    clear_readonly(path)
    shutil.rmtree(path)


def remove_any(path: str) -> None:
    """智能删除：根据路径类型选择删除文件还是目录树。"""
    if os.path.isdir(path):
        remove_tree(path)
    elif os.path.exists(path):
        remove_file(path)


def ensure_parent_is_dir(path: str) -> None:
    """确保路径的所有父级分量都是目录。

    如果某个父级分量是文件，则删除该文件并创建目录。
    """
    parent = os.path.dirname(path)
    if not parent:
        return

    # 收集所有需要检查的父级路径（从最深到最浅）
    parts = []
    current = parent
    while current:
        parts.append(current)
        new_current = os.path.dirname(current)
        if new_current == current:  # 已到根目录
            break
        current = new_current

    # 从最浅到最深检查和修复
    for p in reversed(parts):
        if os.path.exists(p) and not os.path.isdir(p):
            # 是文件，需要删除
            remove_file(p)
        if not os.path.exists(p):
            os.makedirs(p, exist_ok=True)


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。

    复制完成后保留源文件的修改时间。
    """
    # 确保父目录存在且可用
    ensure_parent_is_dir(target)

    # 如果目标存在且是目录，先删除
    if os.path.exists(target) and os.path.isdir(target):
        remove_tree(target)

    # 如果目标文件存在且只读，清除只读属性
    if os.path.exists(target):
        clear_readonly(target)

    # 复制内容
    with open(source, "rb") as src_handle, open(target, "wb") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)

    # 保留源文件的修改时间
    try:
        src_stat = os.stat(source)
        os.utime(target, (src_stat.st_atime, src_stat.st_mtime))
    except OSError:
        pass


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。"""
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                clear_readonly(dirpath)
                os.rmdir(dirpath)
        except OSError:
            pass

