from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional

from . import fsops

CREATE = "create"
UPDATE = "update"
DELETE = "delete"
KEEP = "keep"


@dataclass
class PlanEntry:
    """计划中的一条动作。"""

    action: str
    relpath: str
    source: Optional[str] = None
    target: Optional[str] = None


@dataclass
class Plan:
    """一次同步的完整计划。"""

    entries: List[PlanEntry] = field(default_factory=list)

    def actions(self) -> List[str]:
        return [entry.action for entry in self.entries]

    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。

    先通过签名（大小+修改时间）快速判断；如果签名相同但都存在，
    则进一步比较内容哈希。
    """
    source_sig = fsops.stat_signature(source_path)
    target_sig = fsops.stat_signature(target_path)

    if source_sig is None or target_sig is None:
        return True

    # 签名不同，必定需要更新
    if source_sig != target_sig:
        return True

    # 签名相同，但内容可能不同（修改时间被保留的情况）
    # 比较内容哈希
    source_hash = fsops.compute_file_hash(source_path)
    target_hash = fsops.compute_file_hash(target_path)

    if source_hash is None or target_hash is None:
        return True

    return source_hash != target_hash


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    target_files = fsops.list_entries(target_root)

    entries: List[PlanEntry] = []

    # 使用规范化的键进行比较
    for key in sorted(source_files.keys()):
        source_path = source_files[key]
        target_path = fsops.join(target_root, key)

        if key not in target_files:
            entries.append(
                PlanEntry(
                    CREATE,
                    key,
                    source_path,
                    target_path,
                )
            )
        elif needs_update(source_path, target_path):
            entries.append(
                PlanEntry(UPDATE, key, source_path, target_path)
            )
        else:
            entries.append(
                PlanEntry(KEEP, key, source_path, target_path)
            )

    for key in sorted(target_files.keys()):
        if key not in source_files:
            entries.append(PlanEntry(DELETE, key, None, target_files[key]))

    return Plan(entries)

